30	// CompareOp is an interface for comparing values
31	type CompareOp interface {
32		// CompareLiterals compares two go-mysql-server literals
33		CompareLiterals(ctx *sql.Context, l1, l2 *expression.Literal) (bool, error)
34		// CompareNomsValues compares two noms values
35		CompareNomsValues(ctx context.Context, v1, v2 types.Value) (bool, error)
36		// CompareToNil compares a noms value to nil using sql logic rules
37		CompareToNil(v2 types.Value) (bool, error)
38	}
39	
40	// EqualsOp implements the CompareOp interface implementing equality logic
41	type EqualsOp struct{}
42	
43	// CompareLiterals compares two go-mysql-server literals for equality
44	func (op EqualsOp) CompareLiterals(ctx *sql.Context, l1, l2 *expression.Literal) (bool, error) {
45		n, err := compareLiterals(ctx, l1, l2)
46	
47		if err != nil {
48			return false, err
49		}
50	
51		return n == 0, nil
52	}
53	
54	// CompareNomsValues compares two noms values for equality
55	func (op EqualsOp) CompareNomsValues(_ context.Context, v1, v2 types.Value) (bool, error) {
56		return v1.Equals(v2), nil
57	}
58	
59	// CompareToNil always returns false as values are neither greater than, less than, or equal to nil
60	// except for equality op, the compared value is null.
61	func (op EqualsOp) CompareToNil(v types.Value) (bool, error) {
62		if v == types.NullValue {
63			return true, nil
64		}
65		return false, nil
66	}
