73	// CompareLiterals compares two go-mysql-server literals returning true if the value of the first
74	// is greater than the second.
75	func (op GreaterOp) CompareLiterals(ctx *sql.Context, l1, l2 *expression.Literal) (bool, error) {
76		n, err := compareLiterals(ctx, l1, l2)
77	
78		if err != nil {
79			return false, err
80		}
81	
82		return n > 0, nil
83	}
84	
85	// CompareNomsValues compares two noms values returning true if the of the first
86	// is greater than the second.
87	func (op GreaterOp) CompareNomsValues(ctx context.Context, v1, v2 types.Value) (bool, error) {
88		eq := v1.Equals(v2)
89	
90		if eq {
91			return false, nil
92		}
93	
94		lt, err := v1.Less(ctx, op.vr.Format(), v2)
95	
96		if err != nil {
97			return false, nil
98		}
99	
100		return !lt, err
101	}
