36	// ErrNilOperand ir returned if some or both of the comparison's operands is nil.
37	var ErrNilOperand = errors.NewKind("nil operand found in comparison")
38	
39	// PreciseComparison searches an expression tree for comparison
40	// expressions that require a conversion or type promotion.
41	// This utility helps determine if filter predicates can be pushed down.
42	func PreciseComparison(e sql.Expression) bool {
43		var imprecise bool
44		sql.Inspect(e, func(expr sql.Expression) bool {
45			if cmp, ok := expr.(Comparer); ok {
46				left, right := cmp.Left().Type(), cmp.Right().Type()
47	
48				// integer comparisons are exact
49				if types.IsInteger(left) && types.IsInteger(right) {
50					return true
51				}
52	
53				// string type comparisons are exact
54				if types.IsText(left) && types.IsText(right) {
55					return true
56				}
57	
58				if tupType, ok := right.(types.TupleType); ok {
59					if tupleTypesMatch(left, tupType, types.IsInteger) || tupleTypesMatch(left, tupType, types.IsText) {
60						return true
61					}
62					for _, right := range tupType {
63						if !left.Equals(right) {
64							imprecise = true
65							return false
66						}
67					}
68					return true
69				}
70	
71				// comparisons with type conversions are sometimes imprecise
72				// TODO: this sometimes leads to creating unnecessary filters
73				//  for example, when comparing int key to decimal key (that is too large for integer).
74				if !left.Equals(right) {
75					imprecise = true
76					return false
77				}
78			}
79			return true
80		})
81		return !imprecise
82	}
83	
84	func tupleTypesMatch(left sql.Type, tup types.TupleType, typeCb func(t sql.Type) bool) bool {
85		if !typeCb(left) {
86			return false
87		}
88		for _, right := range tup {
89			if !typeCb(right) {
90				return false
91			}
92		}
93		return true
94	}
