113	func (c *comparison) CollationCoercibility(ctx *sql.Context) (collation sql.CollationID, coercibility byte) {
114		leftCollation, leftCoercibility := sql.GetCoercibility(ctx, c.Left())
115		rightCollation, rightCoercibility := sql.GetCoercibility(ctx, c.Right())
