package expreval

// CompareOp is an interface for comparing values. Implementations translate the result of a comparison (the sign of
// comparing two values) into a boolean, and define how the operator behaves when null is involved.
type CompareOp interface {
	// ApplyCmp takes the result of comparing two values (negative if the first is less than the second, 0 if they are
	// equal, and positive if the first is greater than the second) and returns whether the operator is satisfied.
	ApplyCmp(n int) bool
	// CompareToNil is called when null is involved in a comparison. otherIsNull is true when both sides being compared
	// are null. It returns whether the operator is satisfied in that case.
	CompareToNil(otherIsNull bool) bool
}

// EqualsOp implements the CompareOp interface implementing equality logic
type EqualsOp struct{}

// ApplyCmp returns true only when the compared values are equal.
func (op EqualsOp) ApplyCmp(n int) bool {
	return n == 0
}

// CompareToNil returns true only when both sides are null, as null is only equal to null.
func (op EqualsOp) CompareToNil(otherIsNull bool) bool {
	return otherIsNull
}

// GreaterOp implements the CompareOp interface implementing greater than logic
type GreaterOp struct{}

// ApplyCmp returns true only when the first value is greater than the second.
func (op GreaterOp) ApplyCmp(n int) bool {
	return n > 0
}

// CompareToNil always returns false as values are neither greater than, less than, or equal to null.
func (op GreaterOp) CompareToNil(bool) bool {
	return false
}

// GreaterEqualOp implements the CompareOp interface implementing greater than or equal to logic
type GreaterEqualOp struct{}

// ApplyCmp returns true when the first value is greater than or equal to the second.
func (op GreaterEqualOp) ApplyCmp(n int) bool {
	return n >= 0
}

// CompareToNil always returns false as values are neither greater than, less than, or equal to null.
func (op GreaterEqualOp) CompareToNil(bool) bool {
	return false
}

// LessOp implements the CompareOp interface implementing less than logic
type LessOp struct{}

// ApplyCmp returns true only when the first value is less than the second.
func (op LessOp) ApplyCmp(n int) bool {
	return n < 0
}

// CompareToNil always returns false as values are neither greater than, less than, or equal to null.
func (op LessOp) CompareToNil(bool) bool {
	return false
}

// LessEqualOp implements the CompareOp interface implementing less than or equal to logic
type LessEqualOp struct{}

// ApplyCmp returns true when the first value is less than or equal to the second.
func (op LessEqualOp) ApplyCmp(n int) bool {
	return n <= 0
}

// CompareToNil always returns false as values are neither greater than, less than, or equal to null.
func (op LessEqualOp) CompareToNil(bool) bool {
	return false
